 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Recolor the 13-cell staircase component of 9 to the matching 13-cell
    # component's color (2).
    seen = set()
    for y in range(h):
        for x in range(w):
            if g[y][x] != 9 or (y, x) in seen:
                continue
            stack = [(y, x)]
            seen.add((y, x))
            comp = []
            while stack:
                a, b = stack.pop()
                comp.append((a, b))
                for da, db in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    aa, bb = a + da, b + db
                    if 0 <= aa < h and 0 <= bb < w and (aa, bb) not in seen and g[aa][bb] == 9:
                        seen.add((aa, bb))
                        stack.append((aa, bb))
            if len(comp) == 13:
                for a, b in comp:
                    g[a][b] = 2
                return g
    return g
