 "content": "def transform(grid):
    """For this family, swap colors of distinct regions with identical shapes."""
    g = [row[:] for row in grid]
    h = len(g)
    w = len(g[0])
    background = max(set(v for row in g for v in row), key=lambda c: sum(row.count(c) for row in g))
    seen = set()
    objects = []
    for y in range(h):
        for x in range(w):
            color = g[y][x]
            if color == background or (y, x) in seen:
                continue
            stack = [(y, x)]
            seen.add((y, x))
            cells = []
            while stack:
                a, b = stack.pop()
                cells.append((a, b))
                for da, db in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    aa, bb = a + da, b + db
                    if 0 <= aa < h and 0 <= bb < w and (aa, bb) not in seen and g[aa][bb] == color:
                        seen.add((aa, bb))
                        stack.append((aa, bb))
            y0 = min(a for a, _ in cells)
            x0 = min(b for _, b in cells)
            shape = frozenset((a-y0, b-x0) for a, b in cells)
            objects.append((color, shape, cells))
